'use client'

import { useState } from 'react'

// Bilingual labels for the complaint categories (matches the moderator side).
const TYPE_OPTIONS = [
  { value: 'quality_complaint', label: 'Quality problem / నాణ్యత సమస్య' },
  { value: 'delivery_delay', label: 'Delivery delay / డెలివరీ ఆలస్యం' },
  { value: 'payment_issue', label: 'Payment / refund issue / చెల్లింపు సమస్య' },
  { value: 'other', label: 'Something else / ఇతర' },
]

/**
 * Shared complaint form for consumers. Pass `presetOrderCode` to pin a complaint
 * to a specific order (the field is then locked); leave it out for a general
 * complaint. "Raised by" is filled server-side from the logged-in account.
 */
export default function ComplaintModal({
  presetOrderCode,
  onClose,
  onCreated,
}: {
  presetOrderCode?: string | null
  onClose: () => void
  onCreated: () => void
}) {
  const [type, setType] = useState('quality_complaint')
  const [description, setDescription] = useState('')
  const [orderCode, setOrderCode] = useState(presetOrderCode ?? '')
  const [saving, setSaving] = useState(false)
  const [err, setErr] = useState('')
  const locked = Boolean(presetOrderCode)

  const submit = async () => {
    if (!description.trim()) { setErr('Please describe the problem / సమస్యను వివరించండి'); return }
    setSaving(true); setErr('')
    const r = await fetch('/api/consumer/complaints', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({ type, description: description.trim(), order_code: orderCode.trim() }),
    }).catch(() => null)
    setSaving(false)
    if (!r || !r.ok) {
      const j = r ? await r.json().catch(() => ({})) : {}
      setErr(j?.error ?? 'Could not submit. Try again.')
      return
    }
    onCreated()
  }

  return (
    <div className="fixed inset-0 z-50 bg-black/40 flex items-end sm:items-center justify-center p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-md p-5" onClick={(e) => e.stopPropagation()}>
        <div className="flex items-center justify-between mb-3">
          <p className="font-extrabold text-gray-900">Log a complaint / ఫిర్యాదు</p>
          <button onClick={onClose} className="text-gray-400 text-2xl leading-none p-1">×</button>
        </div>

        {err && <p className="text-xs text-red-600 bg-red-50 border border-red-200 rounded-lg px-3 py-2 mb-3">{err}</p>}

        <label className="block text-xs font-bold text-gray-500 mb-1">Type / రకం</label>
        <select
          value={type}
          onChange={(e) => setType(e.target.value)}
          className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm mb-3 focus:outline-none focus:border-green-500"
        >
          {TYPE_OPTIONS.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
        </select>

        <label className="block text-xs font-bold text-gray-500 mb-1">What happened? / ఏం జరిగింది?</label>
        <textarea
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          rows={4}
          autoFocus
          placeholder="e.g. Tomatoes arrived spoiled / ఉదా: టమోటాలు పాడైపోయాయి"
          className="w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm mb-3 focus:outline-none focus:border-green-500"
        />

        <label className="block text-xs font-bold text-gray-500 mb-1">
          Order code / ఆర్డర్ కోడ్ <span className="font-normal text-gray-300">(optional)</span>
        </label>
        <input
          value={orderCode}
          onChange={(e) => setOrderCode(e.target.value)}
          readOnly={locked}
          placeholder="YFF-1042"
          className={`w-full border border-gray-200 rounded-xl px-3 py-2.5 text-sm mb-4 font-mono focus:outline-none focus:border-green-500 ${locked ? 'bg-gray-50 text-gray-500' : ''}`}
        />

        <div className="flex gap-2">
          <button
            onClick={onClose}
            className="flex-1 border-2 border-gray-200 text-gray-700 font-bold py-3 rounded-xl text-sm active:bg-gray-50"
          >
            Cancel / రద్దు
          </button>
          <button
            onClick={submit}
            disabled={saving}
            className="flex-1 bg-green-700 text-white font-bold py-3 rounded-xl text-sm active:bg-green-800 disabled:opacity-50"
          >
            {saving ? 'Sending… / పంపుతోంది' : 'Submit / సమర్పించండి'}
          </button>
        </div>
      </div>
    </div>
  )
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { getModeratorZone } from '@/lib/moderator-session'
import { normalizeComplaintType } from '@/lib/complaints'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

// GET — the signed-in consumer's own complaints, newest first, each with the
// linked order's human code when there is one.
export async function GET(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })
  const supabase = svc()

  const { data: rows, error } = await supabase
    .from('escalations')
    .select('id, order_id, type, description, status, resolution_notes, resolved_at, created_at, raised_by_phone')
    .eq('raised_by_role', 'consumer')
    .eq('raised_by_id', session.consumerId)
    .order('created_at', { ascending: false })
  if (error) {
    console.error('[YFF consumer/complaints] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  const orderIds = (rows ?? []).map((r) => r.order_id).filter(Boolean) as string[]
  const codeById = new Map<string, string>()
  if (orderIds.length > 0) {
    const { data: orders } = await supabase.from('orders').select('id, order_code').in('id', orderIds)
    for (const o of orders ?? []) codeById.set(o.id, o.order_code ?? '')
  }
  const complaints = (rows ?? []).map((r) => ({
    ...r,
    order_code: r.order_id ? codeById.get(r.order_id) ?? null : null,
  }))
  return NextResponse.json({ complaints })
}

// POST — a consumer files a complaint. "Raised by" is taken from their account
// (never trusted from the client). An optional order_code is accepted and must
// belong to this consumer; it pins the complaint to the right zone's moderator.
//   { type, description, order_code? }
export async function POST(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return NextResponse.json({ error: 'Login required.' }, { status: 401 })
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })
  const b = body as Record<string, unknown>

  const type = normalizeComplaintType(b.type)
  const description = String(b.description ?? '').trim()
  const orderCode = String(b.order_code ?? '').trim()
  if (!description) return NextResponse.json({ error: 'Please describe the problem.' }, { status: 400 })
  if (description.length > 2000) return NextResponse.json({ error: 'Description is too long.' }, { status: 400 })

  // Identity comes from the account, not the request.
  const { data: me } = await supabase
    .from('consumers_auth').select('name, phone').eq('id', session.consumerId).maybeSingle()
  const raisedByName = (me?.name || 'Consumer').trim()
  const raisedByPhone = me?.phone ?? null

  // Resolve the zone. Default to the launch zone; if tied to an order, use that
  // order's farmer's zone so the complaint lands with the right moderator.
  let region_slug = getModeratorZone()
  let order_id: string | null = null
  if (orderCode) {
    const { data: order } = await supabase
      .from('orders')
      .select('id, consumer_id, farmer_id')
      .eq('order_code', orderCode)
      .maybeSingle()
    if (!order) return NextResponse.json({ error: `No order found with code ${orderCode}.` }, { status: 400 })
    if (order.consumer_id !== session.consumerId) {
      return NextResponse.json({ error: 'That order is not on your account.' }, { status: 403 })
    }
    order_id = order.id
    if (order.farmer_id) {
      const { data: farmer } = await supabase
        .from('farmers').select('region_slug').eq('id', order.farmer_id).maybeSingle()
      if (farmer?.region_slug) region_slug = farmer.region_slug
    }
  }

  const { data: inserted, error } = await supabase
    .from('escalations')
    .insert({
      region_slug,
      type,
      description,
      order_id,
      status: 'open',
      raised_by: raisedByName,
      raised_by_role: 'consumer',
      raised_by_id: session.consumerId,
      raised_by_phone: raisedByPhone,
    })
    .select('id')
    .single()
  if (error) {
    console.error('[YFF consumer/complaints] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
  return NextResponse.json({ id: inserted.id })
}

import { createClient } from '@supabase/supabase-js'
import { NextRequest, NextResponse } from 'next/server'
import { isModeratorRequest, getModeratorZone } from '@/lib/moderator-session'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

function svc() {
  return createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )
}

const TYPES = ['delivery_delay', 'quality_complaint', 'payment_issue', 'other'] as const

// GET — every escalation in the moderator's zone, newest first, with the linked
// order's human code (e.g. "Order #YFF-1042") when there is one.
export async function GET(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone(req)
  const supabase = svc()

  const { data: rows, error } = await supabase
    .from('escalations')
    .select('id, order_id, type, description, raised_by, raised_by_role, raised_by_phone, status, resolution_notes, resolved_at, created_at')
    .eq('region_slug', zone)
    .order('created_at', { ascending: false })
  if (error) {
    console.error('[YFF moderator/escalations] query failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }

  // Attach order codes for any escalations that reference an order.
  const orderIds = (rows ?? []).map((r) => r.order_id).filter(Boolean) as string[]
  const codeById = new Map<string, string>()
  if (orderIds.length > 0) {
    const { data: orders } = await supabase.from('orders').select('id, order_code').in('id', orderIds)
    for (const o of orders ?? []) codeById.set(o.id, o.order_code ?? '')
  }
  const escalations = (rows ?? []).map((r) => ({ ...r, order_code: r.order_id ? codeById.get(r.order_id) ?? null : null }))
  return NextResponse.json({ escalations })
}

// POST — log a complaint that came in by phone/WhatsApp. Optionally tie it to an
// order via its order_code (must be an order from a farmer in this zone).
export async function POST(req: NextRequest) {
  if (!isModeratorRequest(req)) {
    return NextResponse.json({ error: 'Moderator login required.' }, { status: 401 })
  }
  const zone = getModeratorZone(req)
  const supabase = svc()

  const body = await req.json().catch(() => null)
  if (!body) return NextResponse.json({ error: 'Invalid body.' }, { status: 400 })
  const b = body as Record<string, unknown>

  const typeRaw = String(b.type ?? 'other')
  const type = (TYPES as readonly string[]).includes(typeRaw) ? typeRaw : 'other'
  const description = String(b.description ?? '').trim()
  let raised_by = String(b.raised_by ?? '').trim() || null
  const orderCode = String(b.order_code ?? '').trim()
  if (!description) return NextResponse.json({ error: 'Describe the complaint.' }, { status: 400 })

  // Callback number of whoever raised it. A complaint must always carry a number
  // so the moderator can follow up — taken from the typed field, then validated.
  // An order_code below can also supply it (and wins if the field was left blank).
  const phoneDigits = String(b.raised_by_phone ?? '').replace(/\D/g, '').slice(-10)
  let raised_by_phone: string | null = phoneDigits.length === 10 ? phoneDigits : null
  if (String(b.raised_by_phone ?? '').trim() && !raised_by_phone) {
    return NextResponse.json({ error: 'Enter a valid 10-digit callback number.' }, { status: 400 })
  }

  // Resolve an optional order_code to an order in this zone. When one is given,
  // the buyer's name and phone come straight off the order so "raised by" is
  // auto-filled and the moderator always has a number to call back on.
  let order_id: string | null = null
  if (orderCode) {
    const { data: order } = await supabase
      .from('orders')
      .select('id, farmer_id, buyer_name, buyer_phone')
      .eq('order_code', orderCode)
      .maybeSingle()
    if (order?.farmer_id) {
      const { data: farmer } = await supabase
        .from('farmers').select('region_slug').eq('id', order.farmer_id).maybeSingle()
      if (farmer?.region_slug !== zone) {
        return NextResponse.json({ error: 'That order is not in your zone.' }, { status: 400 })
      }
      order_id = order.id
      if (!raised_by_phone) raised_by_phone = order.buyer_phone ?? null
      if (!raised_by) raised_by = order.buyer_name?.trim() || null
    } else {
      return NextResponse.json({ error: `No order found with code ${orderCode}.` }, { status: 400 })
    }
  }

  // Enforce the rule: every logged complaint needs a number to call back on.
  if (!raised_by_phone) {
    return NextResponse.json({ error: 'Add a callback number (or an order code that has one).' }, { status: 400 })
  }

  const { data: inserted, error } = await supabase
    .from('escalations')
    .insert({ region_slug: zone, type, description, raised_by, raised_by_role: 'moderator', raised_by_phone, order_id, status: 'open' })
    .select('id')
    .single()
  if (error) {
    console.error('[YFF moderator/escalations] insert failed:', error.message)
    return NextResponse.json({ error: error.message }, { status: 500 })
  }
  return NextResponse.json({ id: inserted.id })
}

import { createHmac, timingSafeEqual } from 'crypto'
import type { NextRequest, NextResponse } from 'next/server'
import { getSessionSecret } from '@/lib/session'

// Moderator session. Like the owner/admin panel, access is gated by a single
// MODERATOR_PASSWORD env var — there is no moderator user table (for the first
// 3 months the founders themselves are the moderator). Successful password
// check sets this cookie; every moderator endpoint verifies it. The HMAC is
// namespaced with `moderator:` so a consumer, farmer, rider, or admin token
// cannot be replayed against moderator routes — that is what keeps the
// /moderator area invisible to every other role.
const COOKIE_NAME = 'yff_moderator'
const TOKEN_TTL_MS = 7 * 24 * 60 * 60 * 1000

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function sign(payload: string): string {
  const secret = getSessionSecret()
  return b64url(createHmac('sha256', secret).update(`moderator:${payload}`).digest())
}

export function getModeratorPassword(): string {
  const pw = process.env.MODERATOR_PASSWORD
  if (!pw || pw.length < 8) {
    throw new Error(
      'MODERATOR_PASSWORD env var is missing or too short. Set an 8+ char value in your environment.',
    )
  }
  return pw
}

// The zone the request's moderator manages. Read from their signed session
// token (stamped with their own region_slug at login), so moderators of
// different zones can all use one deployment and each stays scoped to their
// own region. Falls back to the MODERATOR_ZONE env var when there's no
// moderator session on the request (e.g. routing complaints for other roles).
export function getModeratorZone(req?: NextRequest): string {
  if (req) {
    const t = readModeratorToken(req)
    if (t?.zone) return t.zone
  }
  return process.env.MODERATOR_ZONE || 'tadepalligudem'
}

export function createModeratorSessionToken(zone: string): string {
  const issuedAt = Date.now()
  const zoneB64 = b64url(Buffer.from(zone, 'utf8'))
  const payload = `moderator.${issuedAt}.${zoneB64}`
  return `${payload}.${sign(payload)}`
}

// Parse + verify the moderator cookie. Returns the decoded zone (and issue
// time) when valid, or null. Token shape: moderator.<issuedAt>.<zoneB64>.<sig>
function readModeratorToken(req: NextRequest): { issuedAt: number; zone: string } | null {
  const token = req.cookies.get(COOKIE_NAME)?.value
  if (!token) return null
  const parts = token.split('.')
  if (parts.length !== 4) return null
  const [marker, issuedAtStr, zoneB64, sig] = parts
  if (marker !== 'moderator') return null
  const issuedAt = Number(issuedAtStr)
  if (!Number.isFinite(issuedAt)) return null
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return null
  let expected: string
  try {
    expected = sign(`${marker}.${issuedAtStr}.${zoneB64}`)
  } catch {
    return null
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return null
  if (!timingSafeEqual(a, b)) return null
  let zone = ''
  try {
    zone = Buffer.from(zoneB64.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8')
  } catch {
    return null
  }
  return { issuedAt, zone }
}

export function isModeratorRequest(req: NextRequest): boolean {
  return readModeratorToken(req) !== null
}

export function setModeratorSessionCookie(res: NextResponse, zone: string): void {
  const token = createModeratorSessionToken(zone)
  res.cookies.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: Math.floor(TOKEN_TTL_MS / 1000),
  })
}

export function clearModeratorSessionCookie(res: NextResponse): void {
  res.cookies.set(COOKIE_NAME, '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
}

export const MODERATOR_SESSION_COOKIE_NAME = COOKIE_NAME
